-- The two checklists published on 2026-11-07: The Weeks Before a Wedding
-- (Weddings) and When You and a Sibling Cannot Agree (Siblings).
-- Generated by `python3 tools/checklists_sql.py the-weeks-before-a-wedding
-- when-you-and-a-sibling-cannot-agree`; the repo copy in data/checklists.json
-- is the source. Re-applying is harmless.
insert into public.checklists
  (slug, title, description, category, items, cadence, tags, min_level, published_at)
values
  ('the-weeks-before-a-wedding', 'The Weeks Before a Wedding', 'For the weeks before a wedding, when the list grows faster than the time. It narrows down to the three things that matter, gets the budget said out loud, hands the questions to someone else, and plans for the drop that comes afterward.', 'Weddings', '["Write down the three things that actually matter to you — the rest can go to whoever cares most about it.", "Agree the budget number out loud with each other — a figure left unsaid becomes a fight later.", "Give one person the job of handling questions — you should not be the switchboard for your own wedding.", "Decide now who sits where and stop revisiting it — a seating plan expands to fill all available worry.", "Keep one evening a week with no wedding talk — you are also still two people with a life.", "Say no to one tradition you do not want — a day built on obligation is somebody else''s day.", "Write the hard conversation down before having it — who is not invited is better said once, clearly.", "Put someone in charge of you eating on the day — people forget, and it shows by mid-afternoon.", "Plan the week after as carefully as the day — the drop afterward catches almost everyone off guard."]'::jsonb, 'weekly', array['Stress', 'Family', 'Boundaries']::text[], 1, '2026-11-07T16:00:00+00:00'::timestamptz),
  ('when-you-and-a-sibling-cannot-agree', 'When You and a Sibling Cannot Agree', 'For a disagreement with a brother or sister that has stopped moving. It separates the decision from the old score, puts the practical part in writing, stops the messages going through a parent, and decides what you keep doing either way.', 'Siblings', '["Separate the thing being decided from the old score — most sibling fights are two arguments at once.", "Put the practical question in writing — a message you both reread beats two different memories.", "Name what you are each actually afraid of — the stated disagreement is rarely the whole of it.", "Decide whether you want to be right or close — sometimes you can have both, but choose knowingly.", "Stop relaying messages through a parent — a middle route turns a disagreement into a campaign.", "Offer one thing you can do rather than a verdict — a concrete offer is much harder to argue with.", "Give it a week before answering the worst message — the reply you want to send is never the one that helps.", "Decide what you will keep doing either way — birthdays and check-ins can outlast a disagreement.", "Accept that you may not get the apology — waiting for it hands them the timing."]'::jsonb, 'as needed', array['Family', 'Communication', 'Boundaries']::text[], 1, '2026-11-07T16:00:00+00:00'::timestamptz)
on conflict (slug) do update set
  title        = excluded.title,
  description  = excluded.description,
  category     = excluded.category,
  items        = excluded.items,
  cadence      = excluded.cadence,
  tags         = excluded.tags,
  min_level    = excluded.min_level,
  published_at = excluded.published_at;
